  "pricing.cloud.badge": "Private Beta",
  "pricing.cloud.price": "Auf Anfrage",
  "pricing.cloud.priceNote": "Preis pro Ressource, nicht pro Nutzer",
  "pricing.cloud.desc": "Dasselbe Rebase, von uns betrieben. Heute mit echten Tenants live und während der Private Beta schrittweise geöffnet.",
  "pricing.cloud.cta": "Zugang anfragen",
  "pricing.cloud.feat1": "Verwaltetes Postgres, Backups und TLS",
  "pricing.cloud.feat2": "Deployen über die CLI, zurückrollen in der Konsole",
